#include "adda_protocol.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* External hardcoded vectors from LINK_PROTOCOL_PHY.md, not generated by the
 * implementation under test. Bit packing helpers below use no codec API. */
static const char *body_hex[3] = {
    "01640092090077ab", "017800e8030118f9", "0160099209077d3d"
};
static const char *cadu_hex[3] = {
    "1acffc1dbcd9014c82bf4b2c0b3894c10ddfdc50",
    "1acffc1dbcd902e425bf7178a92646027b434d99",
    "1acffc1dbcd90178796fe89c0b3894fb8771de0a"
};
static const struct ap_command gold[3] = {
    {1,100,2450,0}, {1,120,1000,1}, {1,2400,2450,7}
};
static unsigned checks = 0u;
#define CHECK(x) do { ++checks; if (!(x)) { \
    fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #x); exit(1); } } while (0)

static unsigned nibble(char c)
{
    if (c >= '0' && c <= '9') return (unsigned)(c-'0');
    if (c >= 'a' && c <= 'f') return (unsigned)(c-'a'+10);
    abort();
}
static void from_hex(const char *s, uint8_t *out)
{
    while (*s) { *out++ = (uint8_t)(16u*nibble(s[0])+nibble(s[1])); s += 2; }
}
static void unpack(const uint8_t *bytes, size_t n, uint8_t *bits)
{
    size_t i;
    unsigned j;
    for (i = 0; i < n; ++i) for (j = 0; j < 8u; ++j)
        bits[i*8u+j] = (uint8_t)(((unsigned)bytes[i] >> (7u-j)) & 1u);
}
static int command_equal(const struct ap_command *a, const struct ap_command *b)
{
    return a->version == b->version && a->rx_mhz == b->rx_mhz &&
           a->tx_mhz == b->tx_mhz && a->seq == b->seq;
}
/* Intentionally bypass semantic validation to construct an encoded invalid
 * body. CRC-bad but otherwise noiseless codewords must never be accepted. */
static void raw_body_frame(const uint8_t body[8], uint8_t frame[160])
{
    uint8_t bits[64], asm_bytes[4] = {0x1a,0xcf,0xfc,0x1d};
    unpack(asm_bytes, 4u, frame);
    unpack(body, 8u, bits);
    CHECK(ap_randomize_bits(bits, bits, 64u) == AP_OK);
    CHECK(ap_conv_encode64(bits, frame+32u) == AP_OK);
}
static void replace_crc(uint8_t body[8])
{
    uint16_t c = ap_crc16(body, 6u);
    body[6] = (uint8_t)(c >> 8); body[7] = (uint8_t)c;
}

static void test_gold_and_channel(void)
{
    uint8_t bytes[20], reference[160], encoded[160], body[8], expected_body[8], stream[400];
    struct ap_frame_result result, unchanged;
    struct ap_command parsed;
    unsigned vector, inverted, offset, i, j, successes, rejected, end[3] = {23,5,1};
    size_t n;
    CHECK(ap_crc16((const uint8_t *)"123456789", 9u) == 0x29b1u);
    CHECK(ap_crc16(NULL, 0u) == 0xffffu);
    for (vector = 0; vector < 3u; ++vector) {
        from_hex(body_hex[vector], expected_body);
        from_hex(cadu_hex[vector], bytes);
        unpack(bytes, 20u, reference);
        CHECK(ap_body_build(&gold[vector], body) == AP_OK);
        CHECK(memcmp(body, expected_body, 8u) == 0);
        CHECK(ap_body_parse(expected_body, 8u, &parsed) == AP_OK);
        CHECK(command_equal(&parsed, &gold[vector]));
        CHECK(ap_frame_encode(&gold[vector], encoded) == AP_OK);
        CHECK(memcmp(encoded, reference, 160u) == 0);
        for (inverted = 0; inverted < 2u; ++inverted) for (offset = 0; offset < 9u; ++offset) {
            memset(stream, 0, sizeof(stream));
            for (i = 0; i < 160u; ++i) stream[offset+i] = (uint8_t)(reference[i] ^ inverted);
            CHECK(ap_find_frame(stream, offset+160u, 0u, &result) == AP_OK);
            CHECK(result.bit_offset == offset && result.inverted == inverted);
            CHECK(result.asm_errors == 0u && result.path_metric == 0u && result.end_state == end[vector]);
            CHECK(memcmp(result.body, expected_body, 8u) == 0);
            CHECK(command_equal(&result.command, &gold[vector]));
        }
        successes = rejected = 0u;
        for (i = 0; i < 128u; ++i) {
            memcpy(encoded, reference, sizeof(encoded)); encoded[32u+i] ^= 1u;
            if (ap_find_frame(encoded, 160u, 0u, &result) == AP_OK) {
                CHECK(memcmp(result.body, expected_body, 8u) == 0);
                ++successes;
            } else ++rejected;
        }
        CHECK(successes == 126u && rejected == 2u); /* Untailed end ambiguity. */
        printf("gold%u PASS encode/decode, arbitrary bit offset and polarity; single coded-bit flips %u recovered/%u CRC-rejected\n",
               vector+1u, successes, rejected);
    }
    /* Every pair of ASM bit errors at either polarity must work. */
    from_hex(cadu_hex[0], bytes); unpack(bytes, 20u, reference);
    for (inverted = 0; inverted < 2u; ++inverted) for (i = 0; i < 32u; ++i) for (j = i+1u; j < 32u; ++j) {
        for (offset = 0; offset < 160u; ++offset) encoded[offset] = (uint8_t)(reference[offset] ^ inverted);
        encoded[i] ^= 1u; encoded[j] ^= 1u;
        CHECK(ap_find_frame(encoded, 160u, 0u, &result) == AP_OK);
        CHECK(result.asm_errors == 2u && result.inverted == inverted && command_equal(&result.command, &gold[0]));
    }
    memcpy(encoded, reference, sizeof(encoded)); encoded[0] ^= 1u; encoded[1] ^= 1u; encoded[2] ^= 1u;
    CHECK(ap_find_frame(encoded, 160u, 0u, &result) != AP_OK);
    for (n = 0; n < 160u; ++n) CHECK(ap_find_frame(reference, n, 0u, &result) != AP_OK);
    memset(&result, 0xa5, sizeof(result)); unchanged = result;
    encoded[159] = 2u;
    CHECK(ap_find_frame(encoded, 160u, 0u, &result) == AP_EBIT);
    CHECK(memcmp(&result, &unchanged, sizeof(result)) == 0);
    memset(stream, 0, sizeof(stream));
    CHECK(ap_find_frame(stream, sizeof(stream), 0u, &result) == AP_ENOFRAME);
    CHECK(ap_find_frame(reference, 160u, 161u, &result) == AP_EARG);
    printf("ASM PASS all 992 two-error/polarity combinations, three-error rejection, 160 truncations\n");
}

static void test_validation_and_search(void)
{
    uint8_t body[8], frame[160], stream[327], good_bytes[20], good_bits[160];
    struct ap_frame_result result;
    struct ap_command command = gold[0], parsed;
    unsigned i;
    from_hex(body_hex[0], body);
    for (i = 0; i < 8u; ++i) CHECK(ap_body_parse(body, i, &parsed) == AP_ELENGTH);
    CHECK(ap_body_parse(body, 9u, &parsed) == AP_ELENGTH);
    body[7] ^= 1u;
    CHECK(ap_body_parse(body, sizeof(body), &parsed) == AP_ECRC);
    raw_body_frame(body, frame);
    CHECK(ap_find_frame(frame, 160u, 0u, &result) == AP_ECRC);
    /* Do not stop at an earlier exact ASM with bad CRC. */
    memset(stream, 0, sizeof(stream)); memcpy(stream+7u, frame, sizeof(frame));
    from_hex(cadu_hex[1], good_bytes); unpack(good_bytes, 20u, good_bits);
    for (i = 0; i < 160u; ++i) stream[167u+i] = good_bits[i] ^ 1u;
    CHECK(ap_find_frame(stream, sizeof(stream), 0u, &result) == AP_OK);
    CHECK(result.bit_offset == 167u && result.inverted == 1u && command_equal(&result.command, &gold[1]));
    from_hex(body_hex[0], body); body[0] = 2u; replace_crc(body);
    CHECK(ap_body_parse(body, sizeof(body), &parsed) == AP_EVERSION);
    raw_body_frame(body, frame);
    CHECK(ap_find_frame(frame, 160u, 0u, &result) == AP_EVERSION);
    from_hex(body_hex[0], body); body[1] = 69u; body[2] = 0u; replace_crc(body);
    CHECK(ap_body_parse(body, sizeof(body), &parsed) == AP_ERANGE);
    raw_body_frame(body, frame);
    CHECK(ap_find_frame(frame, 160u, 0u, &result) == AP_ERANGE);
    command.rx_mhz = 70u; command.tx_mhz = 6000u; command.seq = 255u;
    CHECK(ap_body_build(&command, body) == AP_OK);
    CHECK(ap_body_parse(body, 8u, &parsed) == AP_OK && command_equal(&command, &parsed));
    command.rx_mhz = 69u; CHECK(ap_body_build(&command, body) == AP_ERANGE);
    command.rx_mhz = 6001u; CHECK(ap_body_build(&command, body) == AP_ERANGE);
    command.rx_mhz = 70u; command.tx_mhz = 69u; CHECK(ap_body_build(&command, body) == AP_ERANGE);
    command.tx_mhz = 6001u; CHECK(ap_body_build(&command, body) == AP_ERANGE);
    command = gold[0]; command.version = 0u; CHECK(ap_body_build(&command, body) == AP_EVERSION);
    CHECK(ap_body_parse(NULL, 8u, &parsed) == AP_EARG);
    CHECK(ap_frame_encode(NULL, frame) == AP_EARG);
    printf("validation PASS CRC/version/range, endpoint bounds, scan after bad CRC\n");
}

static void test_rf_and_ack(void)
{
    /* Independent fixed packet checked by Python struct.pack and the existing
     * relay_rf_packet.h parser (see test_legacy_compat.c). */
    static const char *packet_hex = "0101c12300110000000005f5e100000000009208088000590849";
    static const char *valid = "rc=0 seq=291 rx_hz=100000000 tx_hz=2450000000\n";
    static const char *bad[] = {
        "OK RX=100 TX=2450\n", "rc=0 seq=291 rx_hz=100000000 tx_hz=2450000000",
        "rc=0 seq=291 rx_hz=100000000 tx_hz=2450000000\ntrailer",
        "rc=2147483648 seq=1 rx_hz=1 tx_hz=2\n", "rc=-2147483649 seq=1 rx_hz=1 tx_hz=2\n",
        "rc=0 seq=16384 rx_hz=1 tx_hz=2\n", "rc=0 seq=-1 rx_hz=1 tx_hz=2\n",
        "rc=0 seq=1 rx_hz=18446744073709551616 tx_hz=2\n",
        "rc=0 seq=1 rx_hz=-1 tx_hz=2\n", "rc=0 seq=1 rx_hz=1 tx_hz=\n",
        "rc=0  seq=1 rx_hz=1 tx_hz=2\n", "rc=+0 seq=1 rx_hz=1 tx_hz=2\n"
    };
    struct ap_ack ack;
    uint8_t packet[26], expected[26];
    unsigned i;
    from_hex(packet_hex, expected);
    CHECK(ap_rf_packet(&gold[0], 0x123u, 0u, 89u, packet) == AP_OK);
    CHECK(memcmp(packet, expected, sizeof(packet)) == 0);
    CHECK(ap_rf_packet(&gold[0], 0x3fffu, 76u, 89u, packet) == AP_OK);
    CHECK(ap_rf_packet(&gold[0], 0x4000u, 0u, 89u, packet) == AP_ERANGE);
    CHECK(ap_rf_packet(&gold[0], 0u, 77u, 89u, packet) == AP_ERANGE);
    CHECK(ap_rf_packet(&gold[0], 0u, 76u, 90u, packet) == AP_ERANGE);
    CHECK(ap_ack_parse((const uint8_t *)valid, strlen(valid), &ack) == AP_OK);
    CHECK(ack.rc == 0 && ack.seq == 291u && ack.rx_hz == UINT64_C(100000000) && ack.tx_hz == UINT64_C(2450000000));
    for (i = 0; i < sizeof(bad)/sizeof(bad[0]); ++i)
        CHECK(ap_ack_parse((const uint8_t *)bad[i], strlen(bad[i]), &ack) != AP_OK);
    valid = "rc=-4 seq=0 rx_hz=100000000 tx_hz=2450000000\r\n";
    CHECK(ap_ack_parse((const uint8_t *)valid, strlen(valid), &ack) == AP_OK && ack.rc == -4 && ack.seq == 0u);
    valid = "rc=-2147483648 seq=16383 rx_hz=18446744073709551615 tx_hz=0\n";
    CHECK(ap_ack_parse((const uint8_t *)valid, strlen(valid), &ack) == AP_OK && ack.rc == INT32_MIN && ack.rx_hz == UINT64_MAX);
    CHECK(ap_ack_parse((const uint8_t *)valid, strlen(valid)+1u, &ack) == AP_EACK); /* embedded NUL */
    CHECK(ap_ack_parse((const uint8_t *)valid, 0u, &ack) == AP_ELENGTH);
    CHECK(ap_ack_parse((const uint8_t *)valid, 96u, &ack) == AP_ELENGTH);
    printf("UDP/ACK PASS fixed 26B vector, exact ASCII format, numeric overflow and malformed rejection\n");
}

static void test_transaction(void)
{
    struct ap_transaction state;
    struct ap_command command = gold[0], other;
    struct ap_ack ack = {0, 0x3fff, UINT64_C(100000000), UINT64_C(2450000000)};
    uint8_t saved_packet[26];
    ap_transaction_init(&state, 0x3fffu);
    command.seq = 254u;
    CHECK(ap_transaction_begin(&state, &command, 0u, 89u) == AP_OK);
    memcpy(saved_packet, state.packet, sizeof(saved_packet));
    CHECK(state.pending == 1u && state.applied_valid == 0u && state.next_transaction_seq == 0u);
    CHECK(ap_transaction_begin(&state, &command, 0u, 89u) == AP_PENDING);
    CHECK(memcmp(saved_packet, state.packet, sizeof(saved_packet)) == 0);
    other = command; other.tx_mhz = 1000u;
    CHECK(ap_transaction_begin(&state, &other, 0u, 89u) == AP_ECONFLICT);
    other = command; other.seq = 255u;
    CHECK(ap_transaction_begin(&state, &other, 0u, 89u) == AP_EBUSY);
    ack.seq = 0u; CHECK(ap_transaction_ack(&state, &ack, 0u) == AP_ESTALE);
    ack.seq = 0x3fffu; ack.rc = -1; CHECK(ap_transaction_ack(&state, &ack, 0u) == AP_EREMOTE);
    ack.rc = 0; ack.tx_hz = UINT64_MAX; CHECK(ap_transaction_ack(&state, &ack, 10000u) == AP_EMISMATCH);
    ack.tx_hz = UINT64_C(2450010001); CHECK(ap_transaction_ack(&state, &ack, 10000u) == AP_EMISMATCH);
    CHECK(state.pending == 1u && state.applied_valid == 0u);
    ack.tx_hz = UINT64_C(2450010000);
    CHECK(ap_transaction_ack(&state, &ack, 10001u) == AP_ERANGE);
    CHECK(ap_transaction_ack(&state, &ack, 10000u) == AP_OK);
    CHECK(state.pending == 0u && state.applied_valid == 1u && state.applied_command.seq == 254u);
    CHECK(ap_transaction_begin(&state, &command, 0u, 89u) == AP_DUPLICATE);
    CHECK(ap_transaction_ack(&state, &ack, 0u) == AP_ESTALE);
    other = command; other.rx_mhz = 120u;
    CHECK(ap_transaction_begin(&state, &other, 0u, 89u) == AP_ECONFLICT);
    command.seq = 255u;
    CHECK(ap_transaction_begin(&state, &command, 0u, 89u) == AP_OK);
    CHECK(state.pending_transaction_seq == 0u && state.applied_command.seq == 254u);
    ap_transaction_abort(&state);
    CHECK(!state.pending && state.applied_command.seq == 254u);
    CHECK(ap_transaction_begin(&state, &command, 0u, 89u) == AP_OK);
    CHECK(state.pending_transaction_seq == 1u);
    ack.seq = 0u; ack.tx_hz = UINT64_C(2450000000);
    CHECK(ap_transaction_ack(&state, &ack, 0u) == AP_ESTALE);
    ack.seq = 1u; CHECK(ap_transaction_ack(&state, &ack, 0u) == AP_OK);
    command.seq = 0u;
    CHECK(ap_transaction_begin(&state, &command, 0u, 89u) == AP_OK); /* air-seq wrap */
    ack.seq = 2u; CHECK(ap_transaction_ack(&state, &ack, 0u) == AP_OK);
    /* V2 specifies equality-only air-sequence deduplication, not ordering.
     * Sender restart/large gaps must not acquire an undocumented half-window. */
    command.seq = 255u; CHECK(ap_transaction_begin(&state, &command, 0u, 89u) == AP_OK);
    ap_transaction_abort(&state);
    command.seq = 128u; CHECK(ap_transaction_begin(&state, &command, 0u, 89u) == AP_OK);
    ap_transaction_abort(&state);
    command.seq = 127u; CHECK(ap_transaction_begin(&state, &command, 0u, 89u) == AP_OK);
    ap_transaction_abort(&state);
    printf("transaction PASS commit only after success, exact retries, stale/conflict/error handling, both sequence wraps\n");
}

int main(void)
{
    test_gold_and_channel();
    test_validation_and_search();
    test_rf_and_ack();
    test_transaction();
    printf("PASS %u assertions; digital frame/control layer only, no network or hardware\n", checks);
    return 0;
}
